215	/// The kind of callee in a field-access function call.
216	enum FieldCallee {
217	    /// A method on a type or on content, with the target value to be added as
218	    /// the first argument of the call.
219	    Method(Func, Value),
220	    /// A plain function to call.
221	    Func(Func),
222	    /// The field access doesn't actually produce a function. This will error in
223	    /// code, but not in math.
224	    NonFunc(Value, HintedString),
225	}
226	
227	/// Evaluate a field-access callee, prioritizing associated functions of the
228	/// value's type, "methods", over fields on the specific value.
229	///
230	/// Calls to fields of a value are only allowed for functions (`assert.eq`),
231	/// types (`str.to-unicode`, `table.cell`), modules (`pdf.attach`), and symbols
232	/// (`arrow.l`).
233	///
234	/// In particular, calls to a field function are not allowed for dictionaries
235	/// because it would be ambiguous. If we did allow it, we would either have to
236	/// prioritize methods or field functions, but both choices are bad:
237	/// - Prioritizing methods would make all new method additions breaking changes.
238	/// - Prioritizing field functions would break methods for certain dictionaries,
239	///   e.g. `(at: x => ...).at(key)`.
240	fn eval_field_callee(
241	    vm: &mut Vm,
242	    access: &SyntaxNode,
243	    field: &str,
244	    field_span: Span,
245	    target: Value,
246	    in_math: bool,
247	) -> SourceResult<FieldCallee> {
248	    let sink = (&mut vm.engine, field_span);
249	
250	    let mut is_method_call = false;
251	    let callee_value = if let Some(method) = target.ty().scope().get(field) {
252	        is_method_call = true;
253	        method.read_checked(sink).clone()
254	    } else if let Value::Content(content) = &target
255	        && let Some(method) = content.elem().scope().get(field)
256	    {
257	        is_method_call = true;
258	        method.read_checked(sink).clone()
259	    } else if matches!(target, Value::Symbol(_) | Value::Type(_) | Value::Module(_)) {
260	        // These types are allowed to use field call syntax on non-methods.
261	        target.field(field, sink).at(field_span)?
262	    } else if let Value::Func(func) = &target {
263	        // Functions can also use field call syntax on non-methods, but not for
264	        // settable fields accessed from context.
265	        match target.field(field, sink).at(field_span) {
266	            Ok(callee_value) => callee_value,
267	            Err(err) => {
268	                if let Some(element) = func.to_element()
269	                    && let Some(field_accessor) = element.settable_field_accessor(field)
270	                {
271	                    let styles = vm.context.styles().at(field_span)?;
272	                    let callee_value = field_accessor(styles);
273	                    bail!(disallowed_field_call_error(
274	                        callee_value,
275	                        access,
276	                        field,
277	                        target,
278	                        in_math
279	                    ));
280	                } else {
281	                    return Err(err);
282	                }
283	            }
284	        }
285	    } else {
286	        // Otherwise we are not allowed to call the field and produce an error.
287	        match target.field(field, sink) {
288	            // The field does exist.
289	            Ok(callee_value) => {
290	                bail!(disallowed_field_call_error(
291	                    callee_value,
292	                    access,
293	                    field,
294	                    target,
295	                    in_math
296	                ));
297	            }
298	            // The field does not exist. We don't try as hard on the error here
299	            // to avoid assuming the user's intent.
300	            Err(_) => {
301	                let (kind, name) = element_or_type_with_name(&target);
302	                bail!(access.span(), "{kind} {name} has no method `{field}`");
303	            }
304	        }
305	    };
306	
307	    vm.trace_at(access.span(), &callee_value);
308	
309	    match callee_value.clone().cast::<Func>() {
310	        Ok(func) if is_method_call => Ok(FieldCallee::Method(func, target)),
311	        Ok(func) => Ok(FieldCallee::Func(func)),
312	        Err(err) => Ok(FieldCallee::NonFunc(callee_value, err)),
313	    }
314	}
