316	/// Produce an error for calls to fields that do exist, but are not allowed to
317	/// be called with field-access syntax.
318	///
319	/// The types that do allow direct field-access calling are `Symbol`, `Type`,
320	/// `Module`, and `Func`. Although functions don't allow settable fields
321	/// accessed from context (like `heading.numbering`) to be called directly.
322	///
323	/// The main types that allow field-access but disallow calling are `Dict`,
324	/// named `Args`, and `Content`.
325	///
326	/// And the remaining types/fields that could produce this error are:
327	/// - `Alignment`: `.x`, `.y`
328	/// - `Length`: `.abs`, `.em`
329	/// - `Rel`: `.ratio`, `.length`
330	/// - `Stroke`: `.cap`, `.dash`, `.join`, `.miter-limit`, `.paint`, `.thickness`
331	/// - `Version`: `.major`, `.minor`, `.patch`
332	fn disallowed_field_call_error(
333	    callee_value: Value,
334	    access: &SyntaxNode,
335	    field: &str,
336	    target: Value,
337	    in_math: bool,
338	) -> SourceDiagnostic {
339	    let is_dict = matches!(target, Value::Dict(_));
340	    let is_named = matches!(target, Value::Args(_));
341	    let mut err = if is_dict {
342	        // Dictionaries get a specific error & hint because they're the easiest
343	        // to attempt this with, and users need to be told directly why it's not
344	        // allowed.
345	        error!(access.span(), "cannot directly call dictionary keys as functions")
346	    } else if is_named {
347	        // Also give the custom error & hint for named arguments.
348	        error!(access.span(), "cannot directly call named argument fields as functions")
349	    } else {
350	        let (kind, name) = element_or_type_with_name(&target);
351	        error!(access.span(), "`{field}` is not a valid method for {kind} `{name}`")
352	    };
353	
354	    if callee_value.clone().cast::<Func>().is_ok() {
355	        err.hint(eco_format!(
356	            "to call the stored function, {}wrap the field access \
357	                in parentheses: `{}({})(..)`",
358	            if in_math { "use code mode and " } else { "" },
359	            if in_math { "#" } else { "" },
360	            access.full_text(),
361	        ));
362	    } else if in_math {
363	        err.hint("try adding a space before the parentheses");
364	    } else {
365	        err.hint(eco_format!(
366	            "to access the `{field}` {}, remove the function arguments: `{}`",
367	            if is_dict {
368	                "key"
369	            } else if is_named {
370	                "argument"
371	            } else {
372	                "field"
373	            },
374	            access.full_text(),
375	        ));
376	    }
377	
378	    if is_dict {
379	        err.hint(
380	            "dictionary keys cannot be used with method syntax as keys could conflict \
381	                with built-in method names",
382	        );
383	    } else if is_named {
384	        err.hint(
385	            "named arguments cannot be used with method syntax as argument names could \
386	                conflict with built-in method names",
387	        );
388	    }
389	
390	    err
391	}
