598	impl Eval for ast::Closure<'_> {
599	    type Output = Value;
600	
601	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
602	        // Evaluate default values of named parameters.
603	        let mut defaults = Vec::new();
604	        for param in self.params().children() {
605	            if let ast::Param::Named(named) = param {
606	                defaults.push(named.expr().eval(vm)?);
607	            }
608	        }
609	
610	        // Collect captured variables.
611	        let captured = {
612	            let mut visitor = CapturesVisitor::new(Some(&vm.scopes), Capturer::Function);
613	            visitor.visit(self.to_untyped());
614	            visitor.finish()
615	        };
616	
617	        // Define the closure.
618	        let closure = Closure {
619	            node: ClosureNode::Closure(self.to_untyped().clone()),
620	            defaults,
621	            captured,
622	            num_pos_params: self
623	                .params()
624	                .children()
625	                .filter(|p| matches!(p, ast::Param::Pos(_)))
626	                .count(),
627	        };
628	
629	        Ok(Value::Func(Func::from(closure).spanned(self.params().span())))
630	    }
631	}
