633	/// Call the function in the context with the arguments.
634	#[comemo::memoize]
635	#[expect(clippy::too_many_arguments)]
636	pub fn eval_closure(
637	    func: &Func,
638	    closure: &LazyHash<Closure>,
639	    world: Tracked<dyn World + '_>,
640	    library: &LazyHash<Library>,
641	    introspector: Tracked<dyn Introspector + '_>,
642	    traced: Tracked<Traced>,
643	    sink: TrackedMut<Sink>,
644	    route: Tracked<Route>,
645	    context: Tracked<Context>,
646	    mut args: Args,
647	) -> SourceResult<Value> {
648	    let (name, params, body) = match closure.node {
649	        ClosureNode::Closure(ref node) => {
650	            let closure =
651	                node.cast::<ast::Closure>().expect("node to be an `ast::Closure`");
652	            (closure.name(), closure.params(), closure.body())
653	        }
654	        ClosureNode::Context(ref node) => {
655	            (None, ast::Params::placeholder(), node.cast().unwrap())
656	        }
657	    };
658	
659	    // Don't leak the scopes from the call site. Instead, we use the scope
660	    // of captured variables we collected earlier.
661	    let mut scopes = Scopes::new(None);
662	    scopes.top = closure.captured.clone();
663	
664	    // Prepare the engine.
665	    let introspector = Protected::from_raw(introspector);
666	    let engine = Engine {
667	        library,
668	        world,
669	        introspector,
670	        traced,
671	        sink,
672	        route: Route::extend(route),
673	    };
674	
675	    // Prepare VM.
676	    let mut vm = Vm::new(engine, context, scopes, body.span());
677	
678	    // Provide the closure itself for recursive calls.
679	    if let Some(name) = name {
680	        vm.define(name, func.clone());
681	    }
682	
683	    let num_pos_args = args.to_pos().len();
684	    let sink_size = num_pos_args.checked_sub(closure.num_pos_params);
685	
686	    let mut sink = None;
687	    let mut sink_pos_values = None;
688	    let mut defaults = closure.defaults.iter();
689	    for p in params.children() {
690	        match p {
691	            ast::Param::Pos(pattern) => match pattern {
692	                ast::Pattern::Normal(ast::Expr::Ident(ident)) => {
693	                    vm.define(ident, args.expect::<Value>(&ident)?);
694	                }
695	                pattern => {
696	                    crate::destructure(
697	                        &mut vm,
698	                        pattern,
699	                        args.expect::<Value>("pattern parameter")?,
700	                    )?;
701	                }
702	            },
703	            ast::Param::Spread(spread) => {
704	                sink = Some(spread.sink_ident());
705	                if let Some(sink_size) = sink_size {
706	                    sink_pos_values = Some(args.consume(sink_size)?);
707	                }
708	            }
709	            ast::Param::Named(named) => {
710	                let name = named.name();
711	                let default = defaults.next().unwrap();
712	                let value =
713	                    args.named::<Value>(&name)?.unwrap_or_else(|| default.clone());
714	                vm.define(name, value);
715	            }
716	        }
717	    }
718	
719	    if let Some(sink) = sink {
720	        // Remaining args are captured regardless of whether the sink is named.
721	        let mut remaining_args = args.take();
722	        if let Some(sink_name) = sink {
723	            if let Some(sink_pos_values) = sink_pos_values {
724	                remaining_args.items.extend(sink_pos_values);
725	            }
726	            vm.define(sink_name, remaining_args);
727	        }
728	    }
729	
730	    // Ensure all arguments have been used.
731	    args.finish()?;
732	
733	    // Handle control flow.
734	    let output = body.eval(&mut vm)?;
735	    match vm.flow {
736	        Some(FlowEvent::Return(_, Some(explicit), _)) => return Ok(explicit),
737	        Some(FlowEvent::Return(_, None, _)) => {}
738	        Some(flow) => bail!(flow.forbidden()),
739	        None => {}
740	    }
741	
742	    Ok(output)
743	}
744	
745	/// A visitor that determines which variables to capture for a closure.
746	pub struct CapturesVisitor<'a> {
747	    external: Option<&'a Scopes<'a>>,
748	    internal: Scopes<'a>,
749	    captures: Scope,
750	    capturer: Capturer,
751	}
752	
753	impl<'a> CapturesVisitor<'a> {
754	    /// Create a new visitor for the given external scopes.
755	    pub fn new(external: Option<&'a Scopes<'a>>, capturer: Capturer) -> Self {
756	        Self {
757	            external,
758	            internal: Scopes::new(None),
759	            captures: Scope::new(),
760	            capturer,
761	        }
762	    }
763	
764	    /// Return the scope of captured variables.
765	    pub fn finish(self) -> Scope {
766	        self.captures
767	    }
768	
769	    /// Visit any node and collect all captured variables.
770	    pub fn visit(&mut self, node: &SyntaxNode) {
771	        match node.cast() {
772	            // Every identifier is a potential variable that we need to capture.
773	            // Identifiers that shouldn't count as captures because they
774	            // actually bind a new name are handled below (individually through
775	            // the expressions that contain them).
776	            Some(ast::Expr::Ident(ident)) => self.capture(ident.get(), Scopes::get),
777	            Some(ast::Expr::MathIdent(ident)) => {
778	                self.capture(ident.get(), Scopes::get_in_math);
779	            }
780	
781	            // Code and content blocks create a scope.
782	            Some(ast::Expr::CodeBlock(_) | ast::Expr::ContentBlock(_)) => {
783	                self.internal.enter();
784	                for child in node.children() {
785	                    self.visit(child);
786	                }
787	                self.internal.exit();
788	            }
789	
790	            // Don't capture the field of a field access.
791	            Some(ast::Expr::FieldAccess(access)) => {
792	                self.visit(access.target().to_untyped());
793	            }
794	            Some(ast::Expr::MathFieldAccess(access)) => {
795	                self.visit(access.target().to_untyped());
796	            }
797	
798	            // A closure contains parameter bindings, which are bound before the
799	            // body is evaluated. Care must be taken so that the default values
800	            // of named parameters cannot access previous parameter bindings.
801	            Some(ast::Expr::Closure(expr)) => {
802	                for param in expr.params().children() {
803	                    if let ast::Param::Named(named) = param {
804	                        self.visit(named.expr().to_untyped());
805	                    }
806	                }
807	
808	                self.internal.enter();
809	                if let Some(name) = expr.name() {
810	                    self.bind(name);
811	                }
812	
813	                for param in expr.params().children() {
814	                    match param {
815	                        ast::Param::Pos(pattern) => {
816	                            for ident in pattern.bindings() {
817	                                self.bind(ident);
818	                            }
819	                        }
820	                        ast::Param::Named(named) => self.bind(named.name()),
821	                        ast::Param::Spread(spread) => {
822	                            if let Some(ident) = spread.sink_ident() {
823	                                self.bind(ident);
824	                            }
825	                        }
826	                    }
827	                }
828	
829	                self.visit(expr.body().to_untyped());
830	                self.internal.exit();
831	            }
832	
833	            // A let expression contains a binding, but that binding is only
834	            // active after the body is evaluated.
835	            Some(ast::Expr::LetBinding(expr)) => {
836	                if let Some(init) = expr.init() {
837	                    self.visit(init.to_untyped());
838	                }
839	
840	                for ident in expr.kind().bindings() {
841	                    self.bind(ident);
842	                }
843	            }
844	
845	            // A for loop contains one or two bindings in its pattern. These are
846	            // active after the iterable is evaluated but before the body is
847	            // evaluated.
848	            Some(ast::Expr::ForLoop(expr)) => {
849	                self.visit(expr.iterable().to_untyped());
850	                self.internal.enter();
851	
852	                let pattern = expr.pattern();
853	                for ident in pattern.bindings() {
854	                    self.bind(ident);
855	                }
856	
857	                self.visit(expr.body().to_untyped());
858	                self.internal.exit();
859	            }
860	
861	            // An import contains items, but these are active only after the
862	            // path is evaluated.
863	            Some(ast::Expr::ModuleImport(expr)) => {
864	                self.visit(expr.source().to_untyped());
865	                if let Some(ast::Imports::Items(items)) = expr.imports() {
866	                    for item in items.iter() {
867	                        self.bind(item.bound_name());
868	                    }
869	                }
870	            }
871	
872	            _ => {
873	                // Never capture the name part of a named pair.
874	                if let Some(named) = node.cast::<ast::Named>() {
875	                    self.visit(named.expr().to_untyped());
876	                    return;
877	                }
878	
879	                // Everything else is traversed from left to right.
880	                for child in node.children() {
881	                    self.visit(child);
882	                }
883	            }
884	        }
885	    }
886	
887	    /// Bind a new internal variable.
888	    fn bind(&mut self, ident: ast::Ident) {
889	        // The concrete value does not matter as we only use the scoping
890	        // mechanism of `Scopes`, not the values themselves.
891	        self.internal
892	            .top
893	            .bind(ident.get().clone(), Binding::detached(Value::None));
894	    }
895	
896	    /// Capture a variable if it isn't internal.
897	    fn capture(
898	        &mut self,
899	        ident: &EcoString,
900	        getter: impl FnOnce(&'a Scopes<'a>, &str) -> HintedStrResult<&'a Binding>,
901	    ) {
902	        if self.internal.get(ident).is_ok() {
903	            return;
904	        }
905	
906	        let binding = match self.external {
907	            Some(external) => match getter(external, ident) {
908	                Ok(binding) => binding.capture(self.capturer),
909	                Err(_) => return,
910	            },
911	            // The external scopes are only `None` when we are doing IDE capture
912	            // analysis, in which case the concrete value doesn't matter.
913	            None => Binding::detached(Value::None),
914	        };
915	
916	        self.captures.bind(ident.clone(), binding);
917	    }
918	}
919	
920	#[cfg(test)]
921	mod tests {
922	    use typst_syntax::parse;
923	
924	    use super::*;
925	
926	    #[track_caller]
927	    fn test(scopes: &Scopes, text: &str, result: &[&str]) {
928	        let mut visitor = CapturesVisitor::new(Some(scopes), Capturer::Function);
929	        let root = parse(text);
930	        visitor.visit(&root);
931	
932	        let captures = visitor.finish();
933	        let mut names: Vec<_> = captures.iter().map(|(k, ..)| k).collect();
934	        names.sort();
935	
936	        assert_eq!(names, result);
937	    }
938	
939	    #[test]
940	    fn test_captures() {
941	        let mut scopes = Scopes::new(None);
942	        scopes.top.define("f", 0);
943	        scopes.top.define("x", 0);
944	        scopes.top.define("y", 0);
945	        scopes.top.define("z", 0);
946	        let s = &scopes;
947	
948	        // Let binding and function definition.
949	        test(s, "#let x = x", &["x"]);
950	        test(s, "#let x; #(x + y)", &["y"]);
951	        test(s, "#let f(x, y) = x + y", &[]);
952	        test(s, "#let f(x, y) = f", &[]);
953	        test(s, "#let f = (x, y) => f", &["f"]);
954	
955	        // Closure with different kinds of params.
956	        test(s, "#((x, y) => x + z)", &["z"]);
957	        test(s, "#((x: y, z) => x + z)", &["y"]);
958	        test(s, "#((..x) => x + y)", &["y"]);
959	        test(s, "#((x, y: x + z) => x + y)", &["x", "z"]);
960	        test(s, "#{x => x; x}", &["x"]);
961	
962	        // Show rule.
963	        test(s, "#show y: x => x", &["y"]);
964	        test(s, "#show y: x => x + z", &["y", "z"]);
965	        test(s, "#show x: x => x", &["x"]);
966	
967	        // For loop.
968	        test(s, "#for x in y { x + z }", &["y", "z"]);
969	        test(s, "#for (x, y) in y { x + y }", &["y"]);
970	        test(s, "#for x in y {} #x", &["x", "y"]);
971	
972	        // Import.
973	        test(s, "#import z: x, y", &["z"]);
974	        test(s, "#import x + y: x, y, z", &["x", "y"]);
975	
976	        // Blocks.
977	        test(s, "#{ let x = 1; { let y = 2; y }; x + y }", &["y"]);
978	        test(s, "#[#let x = 1]#x", &["x"]);
979	
980	        // Field access.
981	        test(s, "#x.y.f(z)", &["x", "z"]);
982	
983	        // Parenthesized expressions.
984	        test(s, "#f(x: 1)", &["f"]);
985	        test(s, "#(x: 1)", &[]);
986	        test(s, "#(x = 1)", &["x"]);
987	        test(s, "#(x += y)", &["x", "y"]);
988	        test(s, "#{ (x, z) = (y, 1) }", &["x", "y", "z"]);
989	        test(s, "#(x.at(y) = 5)", &["x", "y"]);
990	    }
991	
992	    #[test]
993	    fn test_captures_in_math() {
994	        let mut scopes = Scopes::new(None);
995	        scopes.top.define("f", 0);
996	        scopes.top.define("x", 0);
997	        scopes.top.define("y", 0);
998	        scopes.top.define("z", 0);
999	        // Multi-letter variables are required for math.
1000	        scopes.top.define("foo", 0);
1001	        scopes.top.define("bar", 0);
1002	        scopes.top.define("x-bar", 0);
1003	        scopes.top.define("x_bar", 0);
1004	        let s = &scopes;
1005	
1006	        // Basic math identifier differences.
1007	        test(s, "$ x f(z) $", &[]); // single letters not captured.
1008	        test(s, "$ #x #f(z) $", &["f", "x", "z"]);
1009	        test(s, "$ foo f(bar) $", &["bar", "foo"]);
1010	        test(s, "$ #foo[#$bar$] $", &["bar", "foo"]);
1011	        test(s, "$ #let foo = x; foo $", &["x"]);
1012	
1013	        // Math idents don't have dashes/underscores
1014	        test(s, "$ x-y x_y foo-x x_bar $", &["bar", "foo"]);
1015	        test(s, "$ #x-bar #x_bar $", &["x-bar", "x_bar"]);
1016	
1017	        // Named-params.
1018	        test(s, "$ foo(bar: y) $", &["foo"]);
1019	        test(s, "$ foo(x-y: 1, bar-z: 2) $", &["foo"]);
1020	
1021	        // Field access in math.
1022	        test(s, "$ foo.bar $", &["foo"]);
1023	        test(s, "$ foo.x $", &["foo"]);
1024	        test(s, "$ x.foo $", &["foo"]);
1025	        test(s, "$ foo . bar $", &["bar", "foo"]);
1026	        test(s, "$ foo.x.y.bar(z) $", &["foo"]);
1027	        test(s, "$ foo.x-bar $", &["bar", "foo"]);
1028	        test(s, "$ foo.x_bar $", &["bar", "foo"]);
1029	        test(s, "$ #x_bar.x-bar $", &["x_bar"]);
1030	    }
