30	impl<'a> Vm<'a> {
31	    /// Create a new virtual machine.
32	    pub fn new(
33	        engine: Engine<'a>,
34	        context: Tracked<'a, Context<'a>>,
35	        scopes: Scopes<'a>,
36	        target: Span,
37	    ) -> Self {
38	        let inspected = target.id().and_then(|id| engine.traced.get(id));
39	        Self { engine, context, flow: None, scopes, inspected }
40	    }
